/// One frame of the protocol; the JSON object's `type` picks the variant.
#[derive(Debug, Clone, PartialEq)]
pub enum Frame {
    ConnectionReady(ConnectionReady),
    ConnectionDraining(ConnectionDraining),
    Ping(Ping),
    ErrorFrame(ErrorFrame),
    SessionStart(SessionStart),
    UserSaid(UserSaid),
    ToolResult(ToolResult),
    SessionEnd(SessionEnd),
    SessionResumed(SessionResumed),
    AgentSay(AgentSay),
    ToolCall(ToolCall),
    AgentClear(AgentClear),
    SessionResume(SessionResume),
    Pong(Pong),
    Unknown(UnknownFrame),
}

impl Frame {
    /// The wire `type`.
    pub fn frame_type(&self) -> &str {
        match self {
            Frame::ConnectionReady(_) => ConnectionReady::TYPE,
            Frame::ConnectionDraining(_) => ConnectionDraining::TYPE,
            Frame::Ping(_) => Ping::TYPE,
            Frame::ErrorFrame(_) => ErrorFrame::TYPE,
            Frame::SessionStart(_) => SessionStart::TYPE,
            Frame::UserSaid(_) => UserSaid::TYPE,
            Frame::ToolResult(_) => ToolResult::TYPE,
            Frame::SessionEnd(_) => SessionEnd::TYPE,
            Frame::SessionResumed(_) => SessionResumed::TYPE,
            Frame::AgentSay(_) => AgentSay::TYPE,
            Frame::ToolCall(_) => ToolCall::TYPE,
            Frame::AgentClear(_) => AgentClear::TYPE,
            Frame::SessionResume(_) => SessionResume::TYPE,
            Frame::Pong(_) => Pong::TYPE,
            Frame::Unknown(f) => &f.frame_type,
        }
    }

    /// The session the frame names, when it names one.
    pub fn session_id(&self) -> Option<&str> {
        match self {
            Frame::ConnectionReady(_) => None,
            Frame::ConnectionDraining(_) => None,
            Frame::Ping(_) => None,
            Frame::ErrorFrame(f) => f.session_id.as_deref(),
            Frame::SessionStart(f) => Some(&f.session_id),
            Frame::UserSaid(f) => Some(&f.session_id),
            Frame::ToolResult(f) => Some(&f.session_id),
            Frame::SessionEnd(f) => Some(&f.session_id),
            Frame::SessionResumed(f) => Some(&f.session_id),
            Frame::AgentSay(f) => Some(&f.session_id),
            Frame::ToolCall(f) => Some(&f.session_id),
            Frame::AgentClear(f) => Some(&f.session_id),
            Frame::SessionResume(f) => Some(&f.session_id),
            Frame::Pong(_) => None,
            Frame::Unknown(f) => f.session_id.as_deref(),
        }
    }
}

