fn check_session_start(d: Option<&Value>, path: &str) -> Result<(), FrameError> {
    let Some(obj) = object_of(d) else {
        return Err(fail(path, " must be an object"));
    };
    if !obj.contains_key("session_id") {
        return Err(fail(path, ".session_id is required"));
    }
    if !obj.contains_key("call_id") {
        return Err(fail(path, ".call_id is required"));
    }
    if !obj.contains_key("agent_id") {
        return Err(fail(path, ".agent_id is required"));
    }
    if !obj.contains_key("direction") {
        return Err(fail(path, ".direction is required"));
    }
    if !obj.contains_key("from") {
        return Err(fail(path, ".from is required"));
    }
    if !obj.contains_key("to") {
        return Err(fail(path, ".to is required"));
    }
    if !obj.contains_key("session_type") {
        return Err(fail(path, ".session_type is required"));
    }
    if !obj.contains_key("started_at") {
        return Err(fail(path, ".started_at is required"));
    }
    if let Some(v) = obj.get("session_id") {
        let path = &format!("{}.session_id", path);
        let Some(s) = string_of(Some(v)) else {
            return Err(fail(path, " must be a string"));
        };
        if !pattern5().is_match(s) {
            return Err(fail(path, " does not match ^vs_[A-Za-z0-9-]+$"));
        }
    }
    if let Some(v) = obj.get("call_id") {
        let path = &format!("{}.call_id", path);
        let Some(s) = string_of(Some(v)) else {
            return Err(fail(path, " must be a string"));
        };
        if !pattern6().is_match(s) {
            return Err(fail(path, " does not match ^call_[A-Za-z0-9-]+$"));
        }
    }
    if let Some(v) = obj.get("agent_id") {
        let path = &format!("{}.agent_id", path);
        let Some(s) = string_of(Some(v)) else {
            return Err(fail(path, " must be a string"));
        };
        if !pattern7().is_match(s) {
            return Err(fail(path, " does not match ^agent_[A-Za-z0-9-]+$"));
        }
    }
    if let Some(v) = obj.get("direction") {
        let path = &format!("{}.direction", path);
        if !matches!(string_of(Some(v)), Some("inbound" | "outbound")) {
            return Err(fail(path, " is not one of the allowed values"));
        }
    }
    if let Some(v) = obj.get("from") {
        let path = &format!("{}.from", path);
        check_party(Some(v), path)?;
    }
    if let Some(v) = obj.get("to") {
        let path = &format!("{}.to", path);
        check_party(Some(v), path)?;
    }
    if let Some(v) = obj.get("session_type") {
        let path = &format!("{}.session_type", path);
        if !matches!(string_of(Some(v)), Some("text" | "audio")) {
            return Err(fail(path, " is not one of the allowed values"));
        }
    }
    if let Some(v) = obj.get("language") {
        let path = &format!("{}.language", path);
        let Some(s) = string_of(Some(v)) else {
            return Err(fail(path, " must be a string"));
        };
        let _ = s;
    }
    if let Some(v) = obj.get("audio") {
        let path = &format!("{}.audio", path);
        let Some(obj) = object_of(Some(v)) else {
            return Err(fail(path, " must be an object"));
        };
        if !obj.contains_key("stream") {
            return Err(fail(path, ".stream is required"));
        }
        if let Some(v) = obj.get("stream") {
            let path = &format!("{}.stream", path);
            let Some(n) = integer_of(Some(v)) else {
                return Err(fail(path, " must be an integer"));
            };
            if n < 1 {
                return Err(fail(path, " is below 1"));
            }
            if n > 65535 {
                return Err(fail(path, " is above 65535"));
            }
        }
        if let Some(v) = obj.get("sample_rate") {
            let path = &format!("{}.sample_rate", path);
            if !matches!(integer_of(Some(v)), Some(8000 | 16000 | 24000)) {
                return Err(fail(path, " is not one of the allowed values"));
            }
        }
    }
    if let Some(v) = obj.get("max_duration_ms") {
        let path = &format!("{}.max_duration_ms", path);
        let Some(n) = integer_of(Some(v)) else {
            return Err(fail(path, " must be an integer"));
        };
        if n < 1 {
            return Err(fail(path, " is below 1"));
        }
    }
    if let Some(v) = obj.get("context") {
        let path = &format!("{}.context", path);
        if object_of(Some(v)).is_none() {
            return Err(fail(path, " must be an object"));
        }
    }
    if let Some(v) = obj.get("resume") {
        let path = &format!("{}.resume", path);
        check_resume(Some(v), path)?;
    }
    if let Some(v) = obj.get("started_at") {
        let path = &format!("{}.started_at", path);
        let Some(s) = string_of(Some(v)) else {
            return Err(fail(path, " must be a string"));
        };
        let _ = s;
    }
    if string_of(obj.get("session_type")) == Some("audio") {
        if !obj.contains_key("audio") {
            return Err(fail(path, ".audio is required"));
        }
    }
    Ok(())
}

