fn check_session_resume(d: Option<&Value>, path: &str) -> Result<(), FrameError> {
    let Some(obj) = object_of(d) else {
        return Err(fail(path, " must be an object"));
    };
    if !obj.contains_key("session_id") {
        return Err(fail(path, ".session_id is required"));
    }
    if !obj.contains_key("token") {
        return Err(fail(path, ".token is required"));
    }
    if !obj.contains_key("received") {
        return Err(fail(path, ".received is required"));
    }
    if let Some(v) = obj.get("session_id") {
        let path = &format!("{}.session_id", path);
        let Some(s) = string_of(Some(v)) else {
            return Err(fail(path, " must be a string"));
        };
        if !pattern5().is_match(s) {
            return Err(fail(path, " does not match ^vs_[A-Za-z0-9-]+$"));
        }
    }
    if let Some(v) = obj.get("token") {
        let path = &format!("{}.token", path);
        let Some(s) = string_of(Some(v)) else {
            return Err(fail(path, " must be a string"));
        };
        if !pattern3().is_match(s) {
            return Err(fail(path, " does not match ^vsr_[A-Za-z0-9_-]+$"));
        }
        if s.chars().count() < 26 {
            return Err(fail(path, " is shorter than 26"));
        }
        if s.chars().count() > 512 {
            return Err(fail(path, " is longer than 512"));
        }
    }
    if let Some(v) = obj.get("received") {
        let path = &format!("{}.received", path);
        let Some(n) = integer_of(Some(v)) else {
            return Err(fail(path, " must be an integer"));
        };
        if n < 0 {
            return Err(fail(path, " is below 0"));
        }
    }
    Ok(())
}

