fn pattern7() -> &'static Regex {
    static PATTERN: OnceLock<Regex> = OnceLock::new();
    PATTERN
        .get_or_init(|| Regex::new(r#"^agent_[A-Za-z0-9-]+$"#).expect("a pattern of the protocol"))
}

fn pattern8() -> &'static Regex {
    static PATTERN: OnceLock<Regex> = OnceLock::new();
    PATTERN.get_or_init(|| Regex::new(r#"^[0-9*#A-Dw]+$"#).expect("a pattern of the protocol"))
}

fn string_of(v: Option<&Value>) -> Option<&str> {
    v.and_then(Value::as_str)
}

fn bool_of(v: Option<&Value>) -> Option<bool> {
    v.and_then(Value::as_bool)
}

/// A JSON number written without a fraction, as an i64; 1.0 is not an integer here, as it is not for the
/// Python, .NET and Go SDKs.
fn integer_of(v: Option<&Value>) -> Option<i64> {
    v.and_then(Value::as_i64)
}

fn number_of(v: Option<&Value>) -> Option<f64> {
    v.and_then(Value::as_f64)
}

fn object_of(v: Option<&Value>) -> Option<&Map<String, Value>> {
    v.and_then(Value::as_object)
}
